// Embedded Base64 Audio to guarantee immediate zero-network, zero-cache playback
export const NOTIFY_AUDIO_DATA = "data:audio/mp3;base64,";
export const SUCCESS_AUDIO_DATA = "data:audio/mp3;base64,";

let audioCtx: AudioContext | null = null;

function getAudioContext(): AudioContext | null {
  if (typeof window === "undefined") return null;
  const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
  if (!AudioCtx) return null;
  if (!audioCtx) {
    audioCtx = new AudioCtx();
  }
  if (audioCtx.state === "suspended") {
    audioCtx.resume().catch(() => {});
  }
  return audioCtx;
}

export function initAudioUnlock() {
  if (typeof window === "undefined") return;
  const unlock = () => {
    try {
      const ctx = getAudioContext();
      if (ctx && ctx.state === "suspended") {
        ctx.resume().catch(() => {});
      }
      const n = new Audio(NOTIFY_AUDIO_DATA);
      n.volume = 1;
      n.load();
      const s = new Audio(SUCCESS_AUDIO_DATA);
      s.volume = 1;
      s.load();
    } catch {}
  };

  window.addEventListener("pointerdown", unlock, { passive: true });
  window.addEventListener("keydown", unlock, { passive: true });
  window.addEventListener("touchstart", unlock, { passive: true });
  window.addEventListener("scroll", unlock, { passive: true });
}

export function playNotifySound() {
  try {
    const audio = new Audio(NOTIFY_AUDIO_DATA);
    audio.volume = 1;
    const playPromise = audio.play();
    if (playPromise !== undefined) {
      playPromise.catch(() => {
        const onFirstAction = () => {
          const a = new Audio(NOTIFY_AUDIO_DATA);
          a.volume = 1;
          a.play().catch(() => {});
          window.removeEventListener("pointerdown", onFirstAction);
          window.removeEventListener("scroll", onFirstAction);
        };
        window.addEventListener("pointerdown", onFirstAction, { once: true, passive: true });
        window.addEventListener("scroll", onFirstAction, { once: true, passive: true });
      });
    }
  } catch (e) {
    console.error("Audio play failed:", e);
  }
}

export function playOrderSuccessSound() {
  try {
    const audio = new Audio(SUCCESS_AUDIO_DATA);
    audio.volume = 1;
    audio.play().catch(() => {
      try {
        const ctx = getAudioContext();
        if (ctx) ctx.resume();
      } catch {}
    });
  } catch (e) {
    console.error("Success audio error:", e);
  }
}
